import json
from jinja2 import Template

html_template = """<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Global Intentional Homicide Trends: A Multi-Dimensional Analysis (1990–2023)</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        :root {
            --primary-color: #2c3e50;
            --secondary-color: #34495e;
            --accent-color: #e74c3c;
            --bg-color: #f8f9fa;
            --card-bg: #ffffff;
            --text-color: #333333;
            --border-color: #e0e0e0;
        }
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            line-height: 1.6;
            color: var(--text-color);
            background-color: var(--bg-color);
            margin: 0;
            padding: 0;
        }
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 2rem;
        }
        header {
            text-align: center;
            margin-bottom: 3rem;
            padding-bottom: 2rem;
            border-bottom: 2px solid var(--border-color);
        }
        h1 {
            color: var(--primary-color);
            font-size: 2.5rem;
            margin-bottom: 0.5rem;
        }
        .subtitle {
            font-size: 1.2rem;
            color: var(--secondary-color);
            font-style: italic;
        }
        .kpi-dashboard {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 1.5rem;
            margin-bottom: 3rem;
        }
        .kpi-card {
            background-color: var(--card-bg);
            border-radius: 8px;
            padding: 1.5rem;
            text-align: center;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
            border-top: 4px solid var(--primary-color);
        }
        .kpi-card h3 {
            font-size: 0.9rem;
            color: var(--secondary-color);
            margin-top: 0;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }
        .kpi-card .value {
            font-size: 2rem;
            font-weight: bold;
            color: var(--accent-color);
            margin: 0.5rem 0;
        }
        .section {
            background-color: var(--card-bg);
            border-radius: 8px;
            padding: 2rem;
            margin-bottom: 2rem;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
        }
        .section h2 {
            color: var(--primary-color);
            border-bottom: 2px solid var(--border-color);
            padding-bottom: 0.5rem;
            margin-top: 0;
        }
        .chart-container {
            position: relative;
            height: 400px;
            width: 100%;
            margin-top: 1.5rem;
        }
        .split-charts {
            display: flex;
            gap: 2rem;
        }
        .split-charts .chart-container {
            flex: 1;
        }
        p {
            margin-bottom: 1rem;
        }
        ul {
            padding-left: 1.5rem;
            margin-bottom: 1rem;
        }
        li {
            margin-bottom: 0.5rem;
        }
        @media (max-width: 768px) {
            .split-charts {
                flex-direction: column;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>Global Intentional Homicide Trends</h1>
            <p class="subtitle">A Multi-Dimensional Analysis (1990–2023)</p>
            <p>This report presents an evidence-based trend analysis of intentional homicide rates across countries, sexes, and age groups over three decades, drawing on United Nations Office on Drugs and Crime (UNODC) data.</p>
        </header>

        <div class="kpi-dashboard">
            <div class="kpi-card">
                <h3>Global Median Rate</h3>
                <div class="value">{{ kpis.global_median }}</div>
                <p>per 100k (Most Recent Year)</p>
            </div>
            <div class="kpi-card">
                <h3>Male-to-Female Ratio</h3>
                <div class="value">{{ kpis.male_to_female_ratio }}:1</div>
                <p>Global Average</p>
            </div>
            <div class="kpi-card">
                <h3>Highest National Rate</h3>
                <div class="value">{{ kpis.highest_national }}</div>
                <p>per 100k (Most Recent Year)</p>
            </div>
            <div class="kpi-card">
                <h3>Trend (2000s to 2010s)</h3>
                <div class="value">{{ "{:+.1f}".format(kpis.change_2000s_10s) }}%</div>
                <p>Decade-over-Decade Change</p>
            </div>
            <div class="kpi-card">
                <h3>Trend (2010s to 2020s)</h3>
                <div class="value">{{ "{:+.1f}".format(kpis.change_2010s_20s) }}%</div>
                <p>Decade-over-Decade Change</p>
            </div>
        </div>

        <div class="section" id="global-overview">
            <h2>Global Homicide Rate Overview</h2>
            <p>The global trajectory of intentional homicide rates from 1990 to 2023 reveals complex underlying dynamics. While the median rate remains relatively stable, suggesting typical countries experience moderate fluctuations, the global mean is influenced heavily by severe national outliers. The following time-series chart highlights both the average and median reported rates per 100,000 population.</p>
            <p>The average data coverage over the period indicates that approximately <strong>{{ kpis.avg_coverage }}%</strong> of countries consistently report data, necessitating careful interpretation of the observed trends.</p>
            <div class="chart-container">
                <canvas id="globalTrendChart"></canvas>
            </div>
        </div>

        <div class="section" id="regional-comparison">
            <h2>Regional & Country-Level Comparison</h2>
            <p>Significant disparities exist at the national level. The charts below display the countries with the highest and lowest reported homicide rates for their most recent available reporting year. Latin America and the Caribbean often dominate the highest rates, while Western Europe and parts of Asia consistently report the lowest.</p>
            <div class="split-charts">
                <div class="chart-container">
                    <canvas id="top10Chart"></canvas>
                </div>
                <div class="chart-container">
                    <canvas id="bottom10Chart"></canvas>
                </div>
            </div>
        </div>

        <div class="section" id="sex-disparity">
            <h2>Gender Disparity in Homicide Victimization</h2>
            <p>Gender disparity remains a critical and persistent factor in homicide victimization. Globally, men are disproportionately both the victims and perpetrators of intentional homicide. The data highlights a robust male-to-female ratio of <strong>{{ kpis.male_to_female_ratio }}:1</strong>. The temporal visualization underscores that while absolute rates may fluctuate, the substantial gap between male and female victimization remains structurally entrenched.</p>
            <div class="chart-container">
                <canvas id="genderTrendChart"></canvas>
            </div>
        </div>

        <div class="section" id="age-group-analysis">
            <h2>Age Group Analysis</h2>
            <p>Homicide risk is unevenly distributed across the lifespan. Analytical findings demonstrate that youth and young adults are significantly more vulnerable. The chart delineates average global homicide rates segmented by reported age groups, highlighting peak risk periods and indicating targeted demographic intervention points.</p>
            <div class="chart-container">
                <canvas id="ageGroupChart"></canvas>
            </div>
        </div>

        <div class="section" id="notable-trends">
            <h2>Notable Country-Level Trends & Outliers</h2>
            <p>Beyond aggregated global measures, analyzing extreme variances highlights policy successes and emergent crises. Several nations exhibit dramatic shifts over their reporting periods:</p>
            <ul>
                <li><strong>Significant Deteriorations:</strong> Countries experiencing the most profound increases often face rapid escalation in organized crime, political instability, or systemic gang violence.</li>
                <li><strong>Marked Improvements:</strong> Conversely, the most significant decreases are typically correlated with successful long-term public safety initiatives, post-conflict stabilization, or profound socio-economic development.</li>
            </ul>
            <p>It is critical for policy analysts to interrogate these localized outliers, as they offer the most actionable lessons for intervention framing.</p>
        </div>

        <div class="section" id="data-limitations-recommendations">
            <h2>Data Limitations & Policy Recommendations</h2>
            <h3>Data Limitations</h3>
            <ul>
                <li><strong>Unbalanced Panel Data:</strong> The dataset is characterized by significant reporting gaps. Not all countries report annually, and the reporting cohort changes year-over-year. Averages and trends must be contextualized against this missingness.</li>
                <li><strong>United Kingdom Reporting:</strong> As per UNODC documentation, the UK data represents England and Wales exclusively.</li>
                <li><strong>Territorial Double Counting:</strong> Special territories (e.g., Hong Kong, Puerto Rico) are reported independently. Aggregations must be carefully managed to avoid double counting with sovereign parents.</li>
            </ul>
            <h3>Policy Recommendations</h3>
            <ul>
                <li><strong>Targeted Interventions:</strong> Resources should be disproportionately directed toward young male demographics, acknowledging the {{ kpis.male_to_female_ratio }}:1 disparity and the elevated rates in young adult cohorts.</li>
                <li><strong>Regional Focus:</strong> International cooperation and funding must prioritize regions highlighted in the "Top 10" analysis, fostering systemic capacity building and institutional resilience.</li>
                <li><strong>Data Infrastructure:</strong> Stakeholders must invest in harmonized international crime reporting standards to address the <strong>{{ kpis.avg_coverage }}%</strong> reporting coverage, ensuring future policies are guided by more robust, contiguous datasets.</li>
            </ul>
        </div>
    </div>

    <script>
        const chartData = {{ chart_data_json | safe }};

        // Common Chart Options
        const commonOptions = {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    position: 'top',
                }
            }
        };

        // 1. Global Trend Chart
        new Chart(document.getElementById('globalTrendChart'), {
            type: 'line',
            data: {
                labels: chartData.global_trend.labels,
                datasets: [
                    {
                        label: 'Mean Homicide Rate',
                        data: chartData.global_trend.mean,
                        borderColor: '#e74c3c',
                        backgroundColor: 'rgba(231, 76, 60, 0.1)',
                        borderWidth: 2,
                        fill: true,
                        tension: 0.3
                    },
                    {
                        label: 'Median Homicide Rate',
                        data: chartData.global_trend.median,
                        borderColor: '#34495e',
                        borderWidth: 2,
                        borderDash: [5, 5],
                        fill: false,
                        tension: 0.3
                    }
                ]
            },
            options: {
                ...commonOptions,
                scales: {
                    y: {
                        beginAtZero: true,
                        title: { display: true, text: 'Rate per 100k' }
                    }
                }
            }
        });

        // 2. Top 10 Chart
        new Chart(document.getElementById('top10Chart'), {
            type: 'bar',
            data: {
                labels: chartData.top_10.labels,
                datasets: [{
                    label: 'Highest Rates (Most Recent Year)',
                    data: chartData.top_10.data,
                    backgroundColor: '#e74c3c'
                }]
            },
            options: {
                ...commonOptions,
                indexAxis: 'y',
                plugins: {
                    legend: { display: false },
                    title: { display: true, text: 'Highest National Rates' }
                }
            }
        });

        // 3. Bottom 10 Chart
        new Chart(document.getElementById('bottom10Chart'), {
            type: 'bar',
            data: {
                labels: chartData.bottom_10.labels,
                datasets: [{
                    label: 'Lowest Rates (Most Recent Year)',
                    data: chartData.bottom_10.data,
                    backgroundColor: '#2ecc71'
                }]
            },
            options: {
                ...commonOptions,
                indexAxis: 'y',
                plugins: {
                    legend: { display: false },
                    title: { display: true, text: 'Lowest National Rates' }
                }
            }
        });

        // 4. Gender Trend Chart
        new Chart(document.getElementById('genderTrendChart'), {
            type: 'line',
            data: {
                labels: chartData.gender_trend.labels,
                datasets: [
                    {
                        label: 'Male',
                        data: chartData.gender_trend.male,
                        borderColor: '#2980b9',
                        borderWidth: 2,
                        fill: false,
                        tension: 0.3
                    },
                    {
                        label: 'Female',
                        data: chartData.gender_trend.female,
                        borderColor: '#9b59b6',
                        borderWidth: 2,
                        fill: false,
                        tension: 0.3
                    }
                ]
            },
            options: {
                ...commonOptions,
                scales: {
                    y: {
                        beginAtZero: true,
                        title: { display: true, text: 'Rate per 100k' }
                    }
                }
            }
        });

        // 5. Age Group Chart
        new Chart(document.getElementById('ageGroupChart'), {
            type: 'bar',
            data: {
                labels: chartData.age_group.labels,
                datasets: [{
                    label: 'Average Rate by Age Group',
                    data: chartData.age_group.data,
                    backgroundColor: '#f39c12'
                }]
            },
            options: {
                ...commonOptions,
                plugins: {
                    legend: { display: false }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        title: { display: true, text: 'Rate per 100k' }
                    }
                }
            }
        });
    </script>
</body>
</html>
"""

def generate_report():
    with open('/app/chart_data.json', 'r') as f:
        chart_data = json.load(f)
    with open('/app/kpis.json', 'r') as f:
        kpis = json.load(f)

    template = Template(html_template)
    html_content = template.render(
        kpis=kpis,
        chart_data_json=json.dumps(chart_data)
    )

    with open('/app/output/final_report.html', 'w') as f:
        f.write(html_content)

if __name__ == '__main__':
    generate_report()
